// TH15 v1.00b Stage 6 Boss4 (non-spell) — synthetic training card.
// Source entry: st06bs.ecl.txt:464-528 (Boss4), deps Boss4_at:530-574, Boss4_pos:576-585.
// Source window: timerReset at 481; setInterrupt(0,3700,3300,"BossCard4") at 502.
// Card frame 0 starts the phase; 120-frame opening buffer, then a 3300-frame source
// window plus 4 frames of startup margin.
const TIME_LIMIT: int = 3424;
const OPENING_BUFFER: int = 120;

// Source etSprite(0, 8, 6): bullet type 8, colour 6.
const TH15_RICE: int = 480;
const RICE_COLOR: int = 6;

// Source Boss4:523 moveRand(60, 4, 1.9); speed slot inherits linear mode0.
const MOVE_SPEED: fx = 1.9fx;

// Source Boss4_at:557-566 EX 0x40 BOUNCE, b=3 (up|down walls).  Target bounce_arm
// wall bits are L/R/U/D = 1/2/4/8, so up|down = 12.  Target caps at 3 bounces;
// the source values 4 (Hard) and 5 (Lunatic) are clamped to 3 and reported.
xformdef BOUNCE_UPDOWN(n: int) {
    bounce_arm(12, n);
}

// Boss4_at: two etOn waves from owner+(0,-670) and owner+(0,+670); each has
// etDist(640) and EX ANIM's birth displacement position -= 4*velocity, so the
// target spawn distance is 640 - 4*speed along each bullet's own angle.
async sub boss4() {
    set_invuln(65535);
    set_hitbox(25fx);   // Boss init setHitbox(50,50): normal circular 0.5*50
    set_hurtbox(28fx);  // Boss init setHurtbox(56,56): normal circular 0.5*56

    // Boss4:494-496 resets movement, then 504 movePosTime(60,4,0,128).
    // Boss4:479 moveLimit(0,128,280,64) is enforced per step in card_arm_next_step.
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    move_to(0, $self_x, $self_y, EASE_LINEAR);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);

    // Boss4:505-516 animation/sound with wait(30)+wait(50), then wait(60) before
    // the loop.  @Boss4_pos() (enm322 animation loop) is omitted as pure display.
    wait(30);
    wait(50);
    wait(60);

    // Boss4_at difficulty stack values: count E=160 else 320; speed E/N=3, H=4,
    // L=5; BOUNCE count E=1, N=3, H=4, L=5.
    var rank: int = global(GVAR_RANK);
    var count: int = 320;
    var speed: fx = 3fx;
    var bounce: int = 3;
    if rank <= RANK_EASY {
        count = 160;
        bounce = 1;
    } else if rank == RANK_HARD {
        speed = 4fx;
    } else if rank >= RANK_LUNATIC {
        speed = 5fx;
    }
    var dist: fx = 640fx - speed * 4;  // etDist 640 minus ANIM 4*velocity

    // One emitter configuration; each Boss4_at call in the source rebuilt the same
    // parameters through etNew, so the target configures once and only re-fires.
    // The source 320-way ring exceeds sh_count's 255 cap, so it is emitted as two
    // 160-way half-rings offset by half a 320-way step (angle error <= 1 BAM).
    sh_reset(0);
    sh_sprite(0, TH15_RICE, RICE_COLOR);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 160, 1);
    sh_speed(0, speed, 0fx);
    sh_xform(0, BOUNCE_UPDOWN(bounce));
    sh_dist(0, dist);

    loop {
        // Boss4:532-572 Boss4_at body, twice from the two y offsets.
        sh_offset(0, 0fx, -670fx);
        sh_angle(0, 0deg, 0deg);
        sh_fire(0);
        if count > 160 {
            sh_angle(0, 205bam, 0deg);  // half of one 320-way step (204.8 BAM)
            sh_fire(0);
        }
        sh_offset(0, 0fx, 670fx);
        sh_angle(0, 0deg, 0deg);
        sh_fire(0);
        if count > 160 {
            sh_angle(0, 205bam, 0deg);
            sh_fire(0);
        }
        // Boss4:522-524 wait(60), moveRand(60,4,1.9), wait(60); one loop = 120 frames.
        wait(60);
        card_move_rand();
        card_wait(60);
    }
}

// moveRand(60,4,1.9) target helper, following the documented TH18 BossCard1 sample.
// self_int(0) = next source movement step; self_fx(0)/self_fx(1) = direction cos/sin.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 {
        speed = MOVE_SPEED * ((60 - k) as fx) / 60fx;
    }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }   // moveLimit(0,128,280,64)
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

sub card_move_rand() {
    // Source signed random angle R = pi*U; BAM r = U*32768.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Source +/-pi/2 guard, epsilon 0.05 rad = 522 BAM (nearest boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// Independent invulnerable shell (TH15 validation): control only owns the phase.
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Source Boss4:466 lifeSet(20700); entry position (0,128).
    _ = spawn_enemy(0fx, 128fx, 20700, 0, 0, 0, boss4);
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
